/** Changes the turn of this name. A part for a turn the page does not know starts a new turn. */
function within(
  state: ChatState,
  name: string,
  change: (turn: Turn) => Turn,
): ChatState {
  const known = state.turns.some((t) => t.name === name);
  const turns = known
